SELECT REPORT_ID AS "reportId", REPORT_NO AS "reportNo", REPORT_NAME AS "reportName", REPORT_TYPE AS "reportType", REPORT_PERIOD AS "reportPeriod", REPORT_SUMMARY AS "reportSummary", GENERATOR_NAME AS "generatorName", GENERATION_TIME AS "generationTime", REPORT_STATUS AS "reportStatus", DATA_SOURCE AS "dataSource", FILE_SIZE AS "fileSize", CREATE_TIME AS "createTime" FROM TBL_ESTIMATION_REPORT WHERE 1 = 1
AND BOOK_ID = #{bookId}
AND TENANT_ID = #{tenantId}
AND REPORT_TYPE = #{reportType}
AND REPORT_PERIOD = #{reportPeriod}
AND REPORT_PERIOD >= #{startMonth}
AND REPORT_PERIOD <= #{endMonth}
AND REPORT_STATUS = #{reportStatus}
ORDER BY GENERATION_TIME DESC, CREATE_TIME DESC OFFSET #{offset} ROWS FETCH NEXT #{pageSize} ROWS ONLY

SELECT COUNT(1)
FROM TBL_ESTIMATION_REPORT
WHERE 1 = 1

      AND BOOK_ID = #{bookId}


      AND TENANT_ID = #{tenantId}


      AND REPORT_TYPE = #{reportType}


      AND REPORT_PERIOD = #{reportPeriod}


      AND REPORT_PERIOD >= #{startMonth}


      AND REPORT_PERIOD <= #{endMonth}


      AND REPORT_STATUS = #{reportStatus}

mapper.update:
UPDATE TBL_ESTIMATION_REPORT
REPORT_NAME = #{reportName}, REPORT_TYPE = #{reportType}, REPORT_PERIOD = #{reportPeriod}, REPORT_SUMMARY = #{reportSummary}, REPORT_CONTENT = #{reportContent}, REPORT_STATUS = #{reportStatus}, DATA_SOURCE = #{dataSource}, FILE_SIZE = #{fileSize}, FILE_PATH = #{filePath}, REMARK = #{remark}, UPDATE_TIME = SYSDATE
WHERE REPORT_ID = #{reportId}

mapper.select:
SELECT
    COUNT(1) AS "totalCount",
    SUM(CASE WHEN REPORT_STATUS = 1 THEN 1 ELSE 0 END) AS "generatedCount",
    SUM(CASE WHEN REPORT_STATUS = 2 THEN 1 ELSE 0 END) AS "publishedCount",
    COUNT(DISTINCT REPORT_TYPE) AS "reportTypeCount"
FROM TBL_ESTIMATION_REPORT
WHERE REPORT_PERIOD = #{reportPeriod}
  AND BOOK_ID = #{bookId}
  AND TENANT_ID = #{tenantId}
